Проєкт — бекенд інтернет-книгарні (Fastify 5 + Zod + Drizzle/Postgres). Структура: src/contracts/ — Zod-контракти зі snake_case полями, порти в src/contracts/ports.ts (PaymentGateway, Mailer, SecretsProvider); src/modules/<m>/{routes,service,repository,helpers,status}.ts — модулі books, orders, customers; src/adapters/<kind>/ — реалізації портів; src/db/{client,schema,rows}.ts і src/db/migrations; src/platform/{container,errors}.ts — контейнер з overrides для тестів і AppError; пакет packages/pricing-engine — чиста бібліотека розрахунку знижок. Перевірки: npm run typecheck, npm test, npm run lint:deps (dependency-cruiser). Подивись на цей фрагмент з нового PR і скажи, що не так з точки зору архітектури та як виправити:

```ts
// src/modules/digest/routes.ts
import { eq, desc } from 'drizzle-orm';
import * as t from '../../db/schema.js';
import { StripePaymentGateway } from '../../adapters/payments/stripe.js';
import { toBookDto } from '../books/helpers.js';

export default async function digestRoutes(app: FastifyInstance) {
  app.get('/customers/:id/digest', async (req, reply) => {
    const id = (req.params as any).id;
    const payments = new StripePaymentGateway(process.env.STRIPE_KEY!);
    const orders = await app.container.db.select().from(t.orders).where(eq(t.orders.customerId, id)).orderBy(desc(t.orders.createdAt));
    const unpaid = orders.filter(o => o.paidAt === null);
    if (unpaid.length > 3) reply.status(409);
    return { unpaid, books: (await app.container.booksRepo.listForCustomer(id)).map(toBookDto) };
  });
}
```
